if (pose==='dance'){
  torsoBob=-puls*9*eM - swell*3; torsoTwist=Math.sin(bt*Math.PI*0.5)*0.26*eM;
  sL=0.5+Math.sin(bt*Math.PI)*0.95*eM; sR=0.5-Math.sin(bt*Math.PI)*0.95*eM; eL=-0.9-puls*0.5; eR=-0.9-puls*0.5;
  headSnap=Math.sin(bt*Math.PI)*0.22*eM; liftL=stepA*6*eM; liftR=stepB*6*eM; kneeL=stepA*0.4; kneeR=stepB*0.4;
  antGlow=puls; eyeFlash=puls;
} else if (pose==='march'){
  liftL=stepA*24*eM; liftR=stepB*24*eM; kneeL=stepA*0.7; kneeR=stepB*0.7;
  sL=Math.sin(bt*Math.PI+Math.PI)*0.5*eM; sR=Math.sin(bt*Math.PI)*0.5*eM; eL=-0.5; eR=-0.5;
  torsoBob=-(stepA+stepB)*4*eM; headTilt=Math.sin(bt*Math.PI*0.5)*0.06; antGlow=0.3+puls*0.5; eyeFlash=0.3+puls*0.4;
