  if(!chrome){ noStroke(); fill(mLite[0],mLite[1],mLite[2],70); rect(x,y-h/2+h*0.14,w*0.9,h*0.2,r*0.5); fill(mDark[0],mDark[1],mDark[2],75); rect(x,y+h/2-h*0.12,w*0.94,h*0.18,r*0.5); }
  // rivets
  fill(mDark[0],mDark[1],mDark[2],90); const rv=6; for(const sx of [-1,1]) for(const sy of [-1,1]){ ellipse(x+sx*(w/2-rv), y+sy*(h/2-rv), 3.4,3.4); }
  if(rust){ for(let i=0;i<10;i++){ const rr=fr(i*5+x*0.3+y*0.11); const cx=x-w/2+rr*w; const cy=y-h/2+fr(i*5+7+x)*h; fill(18+fr(i)*18,80,42+fr(i*3)*20, 60); ellipse(cx,cy, 2+fr(i*2)*5, 2+fr(i*2)*4); } }
  if(glitch){ for(let b=0;b<5;b++){ const by=y-h/2+fr(b*3+Math.floor(gt*6)+x)*h; const dx=(fr(b*7+Math.floor(gt*8)+y)-0.5)*w*0.5; fill(mLite[0],mLite[1],mLite[2],55); rect(x+dx,by,w*0.9,2.2/k*k*3); } fill(0,90,95,26); rect(x-3,y,w,h*0.5); fill(180,90,95,26); rect(x+3,y,w,h*0.5); }
};

